SELECT gen_random_uuid()::text, 'formula', '$I = \frac{S}{\sqrt3 V_L}$', 'Load Current for Sizing', '$\text{single-phase: } I = \frac{S}{V};\qquad \text{three-phase: } I = \frac{S}{\sqrt3\,V_L} = \frac{P}{\sqrt3\,V_L\,\text{pf}\,\eta}$', '$\text{A}$', 'The current a load draws, the starting point of every conductor and breaker size.', '[{"symbol":"$S$","meaning":"apparent power","unit":"$\\text{VA}$"},{"symbol":"$V_L$","meaning":"line-to-line voltage","unit":"$\\text{V}$"},{"symbol":"$\\text{pf}, \\eta$","meaning":"power factor and efficiency","unit":null}]'::jsonb, 'Use line-to-line voltage with √3. A 3-phase load in VA divided by V alone is 1.73 times too big.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'pec general and definitions' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
