SELECT gen_random_uuid()::text, 'formula', '$VD = kIR''L$', 'Voltage Drop in a Circuit', '$VD = k\,I\,L\,(R''\cos\theta + X''\sin\theta);\qquad k = 2 \text{ (1-phase)},\ \sqrt3 \text{ (3-phase, line to line)}$', '$\text{V}$', 'How much voltage the wires lose between the source and the load.', '[{"symbol":"$I$","meaning":"load current","unit":"$\\text{A}$"},{"symbol":"$L$","meaning":"one-way length","unit":"$\\text{km}$"},{"symbol":"$R'', X''$","meaning":"conductor resistance and reactance per length","unit":"$\\Omega/\\text{km}$"},{"symbol":"$\\theta$","meaning":"power-factor angle","unit":null}]'::jsonb, 'For short building runs the X′ term is small and VD ≈ kIR′L. L is one-way: the 2 already counts the return wire.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'wiring and protection' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
