SELECT gen_random_uuid()::text, 'formula', '$k \times I_{FLC}$', 'Motor Short-Circuit and Ground-Fault Protection', '$I_{\text{OCPD}} \le k\,I_{FLC}:\quad \text{nontime-delay fuse } 300\%;\ \text{dual-element fuse } 175\%;\ \text{instantaneous-trip breaker } 800\%;\ \text{inverse-time breaker } 250\%$', '$\text{A}$', 'The largest fuse or breaker allowed on a motor branch circuit, so it lets the motor start but clears a fault.', '[{"symbol":"$I_{FLC}$","meaning":"motor full-load current from the PEC tables (not the nameplate)","unit":"$\\text{A}$"},{"symbol":"$k$","meaning":"maximum percent for the device type","unit":null}]'::jsonb, 'If the result isn''t a standard size, the next larger standard size is allowed.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'equipment for general use' AND s."active"), NULL, false, 'PENDING', now(), now()
