SELECT gen_random_uuid()::text, 'formula', '$1.35I_C$', 'Capacitor Conductors', '$I_{\text{conductor}} \ge 1.35\,I_{C},\qquad I_C = \frac{Q}{\sqrt3\,V_L}$', '$\text{A}$', 'Power-factor capacitors draw more than their rating (voltage and harmonics), so their conductors carry 135%.', '[{"symbol":"$Q$","meaning":"capacitor bank rating","unit":"$\\text{kvar}$"},{"symbol":"$I_C$","meaning":"rated capacitor current","unit":"$\\text{A}$"}]'::jsonb, 'A capacitor connected on the load side of a motor''s overload relay changes the current the relay sees: reduce its setting.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'equipment for general use' AND s."active"), NULL, false, 'PENDING', now(), now()
