SELECT gen_random_uuid()::text, 'formula', '$I = I_{table}\,k_tk_n$', 'Ampacity Correction and Adjustment', '$I = I_{\text{table}}\,k_t\,k_n;\qquad k_n = 0.80\ (4\text{–}6),\ 0.70\ (7\text{–}9),\ 0.50\ (10\text{–}20 \text{ current-carrying conductors})$', '$\text{A}$', 'A conductor''s allowed current once hotter surroundings and bundling are taken into account.', '[{"symbol":"$I_{\\text{table}}$","meaning":"ampacity from the PEC table","unit":"$\\text{A}$"},{"symbol":"$k_t$","meaning":"ambient-temperature correction factor","unit":null},{"symbol":"$k_n$","meaning":"adjustment for more than three current-carrying conductors in a raceway","unit":null}]'::jsonb, 'A neutral carrying only the unbalanced current doesn''t count; grounding conductors never count.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'wiring methods and materials' AND s."active"), NULL, false, 'PENDING', now(), now()
