SELECT gen_random_uuid()::text, 'constant', '$I_{\text{std}}$', 'Standard Ampere Ratings of Fuses and Breakers', NULL, '$15,\ 20,\ 25,\ 30,\ 35,\ 40,\ 45,\ 50,\ 60,\ 70,\ 80,\ 90,\ 100,\ 110,\ 125,\ 150,\ 175,\ 200,\ 225,\ 250,\ 300,\ 350,\ 400,\ 450,\ 500,\ 600 \ldots\ \text{A}$', 'The fuse and breaker sizes the code calls standard.', '[]'::jsonb, 'Rules that allow "the next larger standard size" mean this list. Fuses also come in 1, 3, 6 and 10 A.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'conductor and overcurrent sizing' AND s."active"), 'Constants', false, 'PENDING', now(), now()
