INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$R = \frac{\rho}{2\pi L}\left(\ln\frac{4L}{a} - 1\right)$', 'Ground Rod Resistance', '$R = \frac{\rho}{2\pi L}\left(\ln\frac{4L}{a} - 1\right)$', '$\Omega$', 'The resistance to earth of one driven rod (Dwight).', '[{"symbol":"$\\rho$","meaning":"soil resistivity","unit":"$\\Omega\\cdot\\text{m}$"},{"symbol":"$L$","meaning":"rod length driven","unit":"$\\text{m}$"},{"symbol":"$a$","meaning":"rod radius","unit":"$\\text{m}$"}]'::jsonb, 'A single rod over 25 Ω needs a second rod at least 1.8 m away. Doubling the length helps far more than a thicker rod.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'grounding and bonding' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'constant', '$\text{A, E, B, F, H}$', 'Insulation Classes', NULL, '$\text{A } 105\,^\circ\text{C};\ \text{E } 120;\ \text{B } 130;\ \text{F } 155;\ \text{H } 180\,^\circ\text{C (maximum hot-spot temperature)}$', 'The temperature an insulation system is rated to last at, for motors and transformers.', '[]'::jsonb, 'Every 10 °C over the rating roughly halves the insulation''s life.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'iec, ieee and nema standards' AND s."active"), 'Constants', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'constant', '$\text{IP}xy$', 'IP Code', NULL, '$\text{first digit } 0\text{–}6: \text{solids (6 dust-tight)};\ \text{second digit } 0\text{–}8: \text{water (7 temporary, 8 continuous immersion)}$', 'How well an enclosure keeps out solids and water (IEC 60529).', '[]'::jsonb, 'IP65: dust-tight, protected against water jets. NEMA ratings (NEMA 4, 4X, 12) say more, such as corrosion and ice.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'iec, ieee and nema standards' AND s."active"), 'Constants', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$s = \frac{wL^2}{8T}$', 'Sag of an Overhead Conductor', '$s = \frac{wL^2}{8T}$', '$\text{m}$', 'How far a line sags at mid-span: Part 2 (supply lines) sets the clearances it must keep above ground.', '[{"symbol":"$w$","meaning":"conductor weight per length","unit":"$\\text{N/m}$"},{"symbol":"$L$","meaning":"span","unit":"$\\text{m}$"},{"symbol":"$T$","meaning":"horizontal tension","unit":"$\\text{N}$"}]'::jsonb, 'The parabola is accurate for sag under about 10% of the span. Higher temperature lengthens the wire and increases sag.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS' AND s."normKey" = 'pec part 2' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Standards & Practices' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
